const d = $input.item.json;
const body = d.body || d;
const agentType = body.agentType || 'seo';

const prompts = {
  reddit: `You are a Reddit marketing expert. Inputs:
- Subreddit(s): ${body.subreddit || ''}
- Topic: ${body.topic || ''}
- Brand Context: ${body.brandContext || ''}

Generate 3 authentic Reddit reply drafts that add genuine value and naturally reference the brand without being promotional. Also provide subreddit recommendations and an engagement strategy.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Reddit Reply Drafts","sections":[{"heading":"Draft Reply 1","content":"..."},{"heading":"Draft Reply 2","content":"..."},{"heading":"Draft Reply 3","content":"..."},{"heading":"Best Subreddits to Target","content":"..."},{"heading":"Reddit Engagement Strategy","content":"..."}]}`,

  seo: `You are a senior SEO strategist. Inputs:
- Website: ${body.websiteUrl || ''}
- Target Keyword: ${body.targetKeyword || ''}
- Industry: ${body.industry || 'General'}

Generate a full SEO content package.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"SEO Content Package","sections":[{"heading":"Keyword Opportunities (15 keywords)","content":"..."},{"heading":"Full SEO Blog Post (800+ words)","content":"..."},{"heading":"Meta Tags & On-Page SEO","content":"..."},{"heading":"Featured Snippet Content","content":"..."},{"heading":"Internal Linking Strategy","content":"..."}]}`,

  writer: `You are a professional brand content writer. Inputs:
- Topic: ${body.topic || ''}
- Brand: ${body.brandName || ''}
- Audience: ${body.audience || ''}
- Tone: ${body.tone || 'Professional'}

Write a comprehensive long-form article.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Long-Form Article","sections":[{"heading":"Full Article (1200+ words)","content":"..."},{"heading":"Social Media Snippets (5 quotes)","content":"..."},{"heading":"Email Newsletter Version (300 words)","content":"..."},{"heading":"Key Takeaways","content":"..."}]}`,

  twitter: `You are an X (Twitter) growth strategist. Inputs:
- Topic: ${body.topic || ''}
- Brand: ${body.brandName || ''}
- Tone: ${body.tone || 'Bold and engaging'}

Generate high-engagement Twitter/X content.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"X (Twitter) Content Drafts","sections":[{"heading":"Standalone Tweets (5)","content":"..."},{"heading":"Thread Draft (7 tweets)","content":"..."},{"heading":"Engagement Hook Tweets (3)","content":"..."},{"heading":"Hashtag Strategy","content":"..."}]}`,

  linkedin_agent: `You are a LinkedIn content strategist. Inputs:
- Topic: ${body.topic || ''}
- Brand/Person: ${body.brandName || ''}
- Audience: ${body.audience || 'B2B professionals'}

Generate LinkedIn content.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"LinkedIn Post Drafts","sections":[{"heading":"Post Draft 1 — Story Format","content":"..."},{"heading":"Post Draft 2 — Insight Format","content":"..."},{"heading":"Post Draft 3 — Engagement Format","content":"..."},{"heading":"Best Posting Schedule & Hashtags","content":"..."}]}`,

  hackernews: `You are a Hacker News community expert. Inputs:
- Topic: ${body.topic || ''}
- Brand/Product: ${body.brandName || ''}
- Value Proposition: ${body.value || ''}

Generate an HN engagement strategy.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Hacker News Engagement Strategy","sections":[{"heading":"Show HN Post Draft","content":"..."},{"heading":"Comment Draft 1","content":"..."},{"heading":"Comment Draft 2","content":"..."},{"heading":"Comment Draft 3","content":"..."},{"heading":"Thread Targeting Strategy","content":"..."}]}`,

  geo: `You are a Generative Engine Optimization (GEO) expert specializing in getting brands cited in ChatGPT and Google AI Overviews. Inputs:
- Brand: ${body.brandName || ''}
- Keywords: ${body.keywords || ''}
- Description: ${body.description || ''}

Generate a complete GEO optimization package.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"GEO Optimization Package","sections":[{"heading":"AI Citation-Ready Content Blocks","content":"..."},{"heading":"Entity & Authority Building Strategy","content":"..."},{"heading":"FAQ Content for AI Overviews (10 Q&As)","content":"..."},{"heading":"Schema Markup Recommendations","content":"..."},{"heading":"Content Distribution Plan for AI Citations","content":"..."}]}`,

  coding: `You are a technical SEO engineer. Inputs:
- Website: ${body.websiteUrl || ''}
- Issue/Goal: ${body.issue || ''}
- Tech Stack: ${body.techStack || 'Unknown'}

Generate technical SEO fixes with code.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Technical SEO Fix Plan","sections":[{"heading":"Diagnosis & Priority Issues","content":"..."},{"heading":"Code Fix 1 (Primary)","content":"..."},{"heading":"Code Fix 2 (Secondary)","content":"..."},{"heading":"Performance Optimizations","content":"..."},{"heading":"Testing & Verification Checklist","content":"..."}]}`,

  ugc_videos: `You are a UGC video content strategist. Inputs:
- Product/Service: ${body.product || ''}
- Style: ${body.style || ''}
- Audience: ${body.audience || 'General consumers'}
- Platforms: ${body.platforms || 'Instagram, TikTok'}

Generate UGC video briefs and scripts.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"UGC Video Brief & Scripts","sections":[{"heading":"Video Brief & Creative Direction","content":"..."},{"heading":"Full Script — Version 1 (60 seconds)","content":"..."},{"heading":"Short Script — Version 2 (30 seconds)","content":"..."},{"heading":"Hook Options (5 variations)","content":"..."},{"heading":"Platform Adaptations & Hashtags","content":"..."}]}`
};

const prompt = prompts[agentType] || prompts.seo;
return { json: { ...body, agentType, _agentPrompt: prompt } };

const geminiResp = $input.item.json;
const orig = $('Build Agent Prompt').first().json;

const rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!rawText) {
  return { json: { success: false, error: 'Gemini returned no content', agentResult: { title: 'Error', sections: [{ heading: 'Error', content: 'The AI agent did not return content. Please try again.' }] } } };
}

let agentResult;
try {
  // Strip markdown code fences if present
  let clean = rawText.trim();
  clean = clean.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  clean = clean.replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  agentResult = JSON.parse(clean);
} catch (e) {
  // Fallback: wrap raw text as a single section
  agentResult = {
    title: orig.agentType + ' Results',
    sections: [{ heading: 'Generated Content', content: rawText }]
  };
}

return { json: { success: true, agentType: orig.agentType, agentResult } };
